CREATE COLUMN TABLE "TEST_AP"."PKL1" ("AbsEntry" INTEGER CS_INT NOT NULL , "PickEntry" INTEGER CS_INT NOT NULL , "OrderEntry" INTEGER CS_INT, "OrderLine" INTEGER CS_INT, "PickQtty" DECIMAL(21,6) CS_FIXED, "PickStatus" NVARCHAR(1) DEFAULT 'R', "RelQtty" DECIMAL(21,6) CS_FIXED, "LogInsac" INTEGER CS_INT, "PrevReleas" DECIMAL(21,6) CS_FIXED, "BaseObject" INTEGER CS_INT, PRIMARY KEY ("AbsEntry", "PickEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."PKL1" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$OrderEntry$OrderLine$','OrderEntry','OrderLine'));
CREATE INDEX "PKL1_ORDER" ON "TEST_AP"."PKL1" ( "OrderEntry" ASC, "OrderLine" ASC )